// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;

// Session:
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};

  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.mínimo = Number(String(obj.mínimo).replace(/[^\d,]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// Dicionário com os templates estáticos definidos na Etapa 4
const templates = {
  "Conservador": "Olá {Nome}, seu saldo atual é {Saldo}. Foco em renda fixa e segurança para proteger seu patrimônio.",
  "Moderado": "Olá {Nome}, seu saldo atual é {Saldo}. Recomendamos um mix equilibrado entre renda fixa e variável.",
  "Arrojado": "Olá {Nome}, seu saldo atual é {Saldo}. Ênfase em ações e maior potencial de retorno para sua carteira."
};

// Processa cada item que chega do nó anterior (ex: planilha ou tabela de clientes)
return $input.all().map(item => {
  const cliente = item.json;
  const perfil = cliente.Perfil;

  // Seleciona o template correspondente ao perfil do cliente
  let templateEscolhido = templates[perfil] || "Olá {Nome}, bem-vindo à nossa assessoria financeira!";

  // Substitui as tags pelas informações reais do cliente
  let mensagemEstatica = templateEscolhido
    .replace("{Nome}", cliente.Nome)
    .replace("{Saldo}", cliente.Saldo);

  return {
    json: {
      ...cliente,
      mensagemEstatica: mensagemEstatica,
      // Propriedade extra útil para facilitar a integração com a IA na Etapa 5
      promptSugeridoParaIA: `Atue como um Assessor de Investimentos. Escreva uma mensagem comercial humanizada e personalizada para o cliente ${cliente.Nome}, que tem um saldo de ${cliente.Saldo} e perfil ${perfil}.`
    }
  };
});

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();
